def dedupe_contacts(rows):
    DIGITS = "0123456789"

    def norm_email(raw):
        e = (raw or "").strip().lower()
        if e.count("@") != 1:
            return ""
        local, domain = e.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        if not local:
            return ""
        if "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return local + "@" + domain

    def norm_phone(raw):
        d = "".join(c for c in (raw or "") if c in DIGITS)
        if len(d) == 11 and d[0] == "1":
            d = d[1:]
        return d if len(d) == 10 else ""

    # Step 1: normalize and drop rows with no valid email and no valid phone
    recs = []  # (original_index, row, email, phone, last_key)
    for i, r in enumerate(rows):
        email = norm_email(r.get("email"))
        phone = norm_phone(r.get("phone"))
        if not email and not phone:
            continue
        last_key = (r.get("last_name") or "").strip().casefold()
        recs.append((i, r, email, phone, last_key))

    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the smaller position as root (positions follow input order)
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    # Step 2: union rows sharing an email, or a phone + non-empty last name
    by_email = {}
    by_phone_last = {}
    for pos, (_, _, email, phone, last_key) in enumerate(recs):
        if email:
            if email in by_email:
                union(pos, by_email[email])
            else:
                by_email[email] = pos
        if phone and last_key:
            key = (phone, last_key)
            if key in by_phone_last:
                union(pos, by_phone_last[key])
            else:
                by_phone_last[key] = pos

    groups = {}
    for pos in range(n):
        groups.setdefault(find(pos), []).append(pos)

    # Step 3: build one output dict per group
    def updated_of(pos):
        return (recs[pos][1].get("updated") or "").strip()

    results = []
    for members in groups.values():
        members.sort()  # input order
        # most recent first; stable sort keeps earlier input row first on ties
        ordered = sorted(members, key=updated_of, reverse=True)

        def pick_field(name):
            for pos in ordered:
                v = (recs[pos][1].get(name) or "").strip()
                if v:
                    return v
            return ""

        email = ""
        for pos in ordered:
            if recs[pos][2]:
                email = recs[pos][2]
                break

        phone = ""
        for pos in ordered:
            if recs[pos][3]:
                phone = recs[pos][3]
                break

        tags = set()
        for pos in members:
            for t in (recs[pos][1].get("tags") or "").split(";"):
                t = t.strip().lower()
                if t:
                    tags.add(t)

        opted_out = "N"
        for pos in members:
            if (recs[pos][1].get("opted_out") or "").strip().upper() == "Y":
                opted_out = "Y"
                break

        results.append((
            recs[members[0]][0],  # earliest original input index in the group
            {
                "first_name": pick_field("first_name"),
                "last_name": pick_field("last_name"),
                "email": email,
                "phone": phone,
                "zip": pick_field("zip"),
                "tags": ";".join(sorted(tags)),
                "opted_out": opted_out,
                "updated": max(updated_of(pos) for pos in members),
            },
        ))

    results.sort(key=lambda t: t[0])
    return [d for _, d in results]
```

Notes:

- **Opt-outs:** the function keeps opted-out people in the output with `opted_out == "Y"`, as the rules specify. Before sending, filter them out, e.g. `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N" and p["email"]]`. The `email` check also skips people who only have a valid phone.
- **Limits of matching:** an opt-out can only propagate within a matched group. If someone opted out under one email and appears under a different email with no shared phone and last name, they'll look like two people. Under these rules that can't be detected.
- **Date comparison:** `updated` values are compared as strings, which is correct for ISO dates like `2026-10-02`.
